package vn.svframe.svframelib.script.variable;import java.util.*;import java.util.concurrent.ConcurrentHashMap;public class VariableList implements VariableContainer{public static final VariableList SERVER=new VariableList(VariableScope.SERVER);private final VariableScope scope;private final Map<String,Variable<?>> values=new ConcurrentHashMap<>();public VariableList(VariableScope scope){this.scope=Objects.requireNonNull(scope);}public VariableScope getScope(){return scope;}public Variable<?> getVariable(String path){if(path==null)return null;String p=path.trim();int dot=p.indexOf('.');Variable<?> base=values.get((dot<0?p:p.substring(0,dot)).toLowerCase(Locale.ROOT));return base==null?null:dot<0?base:base.getVariable(p.substring(dot+1));}public void registerVariable(Variable<?> variable){values.put(variable.getName().toLowerCase(Locale.ROOT),variable);}public Collection<Variable<?>> values(){return List.copyOf(values.values());}}